fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    let mut reversed = Vec::with_capacity(n); // Create a new vector with the same capacity

    for i in (0..n).rev() { // Iterate from the last index to the first
        reversed.push(a[i]); // Push the characters in reverse order
    }

    reversed // Return the new reversed vector
}